<template><div class="form-page"><el-form label-width="150px" label-position="left"><MetadataEditor :model="localForm" title="基础配置" /><el-card shadow="never"><template #header>StatefulSet 配置</template><div class="grid-two"><el-form-item label="服务名"><el-input v-model="localForm.serviceName" /></el-form-item><el-form-item label="副本数"><el-input-number v-model="localForm.replicas" :min="1" /></el-form-item><el-form-item label="Pod 管理策略"><el-select v-model="localForm.podManagementPolicy" placeholder="可不选"><el-option label="不指定" value="" /><el-option label="OrderedReady" value="OrderedReady" /><el-option label="Parallel" value="Parallel" /></el-select></el-form-item><el-form-item label="更新策略"><el-select v-model="localForm.strategy.type" placeholder="可不选"><el-option label="不指定" value="" /><el-option label="滚动更新" value="RollingUpdate" /><el-option label="删除时更新" value="OnDelete" /></el-select></el-form-item></div><el-form-item label="选择器标签"><KeyValueEditor v-model="localForm.matchLabels" /></el-form-item><ArrayEditor v-model="localForm.volumeClaimTemplates" title="存储声明模板" label-key="metadata.name" :create-item="createVolumeClaimTemplate"><template #default="{ item }"><div class="grid-four"><el-form-item label="名称"><el-input v-model="item.metadata.name" /></el-form-item><el-form-item label="存储类"><el-input v-model="item.storageClassName" /></el-form-item><el-form-item label="访问模式"><el-select v-model="item.accessModes"><el-option label="ReadWriteOnce" value="ReadWriteOnce" /><el-option label="ReadOnlyMany" value="ReadOnlyMany" /><el-option label="ReadWriteMany" value="ReadWriteMany" /></el-select></el-form-item><el-form-item label="存储大小"><el-input v-model="item.requests.storage" placeholder="10Gi" /></el-form-item></div></template></ArrayEditor></el-card><PodTemplateEditor :model="localForm.podTemplate" title="Pod 模板" /></el-form></div></template>
<script setup lang="ts">import { computed } from 'vue'; import type { StatefulSetFormData } from '@/types/k8s'; import { createVolumeClaimTemplate } from '@/composables/useK8sSchema'; import MetadataEditor from '@/components/common/MetadataEditor.vue'; import KeyValueEditor from '@/components/common/KeyValueEditor.vue'; import PodTemplateEditor from '@/components/common/PodTemplateEditor.vue'; import ArrayEditor from '@/components/common/ArrayEditor.vue'; const props = defineProps<{ modelValue: StatefulSetFormData }>(); const emit = defineEmits<{ 'update:modelValue':[value:StatefulSetFormData] }>(); const localForm = computed({ get:()=>props.modelValue, set:(value:StatefulSetFormData)=>emit('update:modelValue', value) });</script><style scoped>.form-page{display:grid;gap:16px}.grid-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 32px}.grid-four{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}</style>
